# Analyze the pattern from the demo
# Input: 2 (background), 6 (object)
# Output: 1s appear around 6s (4 direct neighbors)
# Background 2 -> stays 2, unless neighbor to 6, then becomes 1
# Object 6 -> stays 6

# Apply to test input:
# Background is 7, objects are 3
# 7s stay 7, unless neighbor to 3, then become 1
# 3s stay 3

grid = [
    [7, 7, 7, 3, 3, 7, 3, 7, 7, 7, 7, 7, 7, 7, 7, 7, 3, 7, 7, 7, 7, 7, 7, 7, 7, 3],
    [7, 3, 7, 7, 3, 7, 7, 7, 7, 7, 7, 7, 7, 7, 7, 3, 3, 3, 7, 7, 3, 3, 3, 7, 7, 3]
]

rows, cols = 2, 26

# Find all positions of 3
positions_3 = set()
for r in range(rows):
    for c in range(cols):
        if grid[r][c] == 3:
            positions_3.add((r, c))

print("Positions of 3:", positions_3)

# Build output grid
output = []
for r in range(rows):
    row_out = []
    for c in range(cols):
        val = grid[r][c]
        # Check if this cell is a neighbor to any 3
        is_neighbor = False
        if (r, c-1) in positions_3:
            is_neighbor = True
        if (r, c+1) in positions_3:
            is_neighbor = True
        if (r-1, c) in positions_3:
            is_neighbor = True
        if (r+1, c) in positions_3:
            is_neighbor = True

        if val == 3:
            row_out.append(3)
        else:
            # background becomes 1 if neighbor, stays 7 otherwise
            if is_neighbor:
                row_out.append(1)
            else:
                row_out.append(7)
    output.append(row_out)

print("\nOutput grid:")
for r in range(rows):
    print(output[r])

